def _tipo_legado_de_nome(nome: str) -> str:
    lower = (nome or "").lower()
    if "ouvidoria" in lower:
        return "ouvidoria"
    if "zeladoria" in lower:
        return "zeladoria"
    return ""


def migrar_categorias_texto_para_fk(apps, schema_editor):
    Categoria = apps.get_model("catalogo", "CategoriaCatalogo")
    Servico = apps.get_model("catalogo", "ServicoCatalogo")

    cache: dict[str, uuid.UUID] = {}
    ordem = 0

    for nome in (
        Servico.objects.order_by("categoria")
        .values_list("categoria_nome", flat=True)
        .distinct()
    ):
        nome = (nome or "").strip()
        if not nome:
            continue
        slug = slugify(nome).replace("-", "_") or "outros"
        base = slug
        i = 2
        while Categoria.objects.filter(slug=slug).exists():
            slug = f"{base}_{i}"
            i += 1

        ordem += 10
        cat = Categoria.objects.create(
            nome=nome,
            slug=slug[:80],
            ordem=ordem,
            tipo_legado=_tipo_legado_de_nome(nome),
            ativo=True,
        )
        cache[nome] = cat.id

    for servico in Servico.objects.all().iterator():
        nome = (servico.categoria_nome or "").strip()
        cat_id = cache.get(nome)
        if cat_id:
            servico.categoria_id = cat_id
            servico.save(update_fields=["categoria_id"])


def reverter_migracao(apps, schema_editor):
    Categoria = apps.get_model("catalogo", "CategoriaCatalogo")
    Servico = apps.get_model("catalogo", "ServicoCatalogo")

    for servico in Servico.objects.select_related("categoria").iterator():
        if servico.categoria_id and servico.categoria:
            servico.categoria_nome = servico.categoria.nome
            servico.save(update_fields=["categoria_nome"])

    Categoria.objects.all().delete()


